window.BOSS_KB_FILES = ["boss_kb.pl","boss_derive.pl","boss_rules.pl","boss_infer.pl","boss_advice.pl"];
window.BOSS_KB = {"boss_kb.pl":"% ============================================================\n% B0SS - Business Opportunity Screening System\n% boss_kb.pl - Fixed domain knowledge base\n%\n% 25 unconditional facts, transcribed verbatim from SRS section 5.\n% These never change between assessments. Session facts asserted\n% from the user's answers live in working memory, not here.\n%\n% Count: 7 supported_business + 3 safe_funding + 3 dangerous_funding\n%      + 4 demand_level + 4 cash_cycle_type + 4 legal_value = 25\n% ============================================================\n\n% --- Business types B0SS is allowed to screen (7) ---\nsupported_business(service).\nsupported_business(retail).\nsupported_business(online).\nsupported_business(education).\nsupported_business(professional_service).\nsupported_business(food).\nsupported_business(owner_trade).\n\n% --- Funding sources that do not endanger the household (3) ---\nsafe_funding(own_savings).\nsafe_funding(family_interest_free).\nsafe_funding(formal_affordable).\n\n% --- Funding sources that trigger the R10 absolute override (3) ---\ndangerous_funding(informal_high_interest).\ndangerous_funding(pawned_asset).\ndangerous_funding(home_secured_loan).\n\n% --- Strength of evidence that somebody will actually pay (4) ---\ndemand_level(none).\ndemand_level(anecdotal).\ndemand_level(observed).\ndemand_level(validated).\n\n% --- How money moves in and out of the business (4) ---\ncash_cycle_type(advance_payment).\ncash_cycle_type(on_delivery).\ncash_cycle_type(long_credit).\ncash_cycle_type(heavy_stock).\n\n% --- Licensing / legal position (4) ---\nlegal_value(none_required).\nlegal_value(routine).\nlegal_value(unknown).\nlegal_value(blocking).\n","boss_derive.pl":"% ============================================================\n% B0SS - boss_derive.pl\n% Working-memory declarations and derived values.\n%\n% SRS section 4.2: these are CALCULATED from user answers and are\n% never asked as separate questions.\n%\n% The clauses in this file are derivation parameters, NOT domain\n% facts: the 25 knowledge-base facts of SRS section 5 remain\n% exactly 25. See DECISIONS.md, decision 1.\n% ============================================================\n\n% --- Session facts, asserted by the interface (SRS 4.1) ---\n:- dynamic(business_type/1).\n:- dynamic(venture_type/1).\n:- dynamic(channel_type/1).\n:- dynamic(demand_evidence/1).\n:- dynamic(target_customer/1).\n:- dynamic(repeat_demand/1).\n:- dynamic(price_status/1).\n:- dynamic(owner_experience/1).\n:- dynamic(owner_time/1).\n:- dynamic(reversibility/1).\n:- dynamic(startup_cost/1).\n:- dynamic(monthly_cost/1).\n:- dynamic(capital_available/1).\n:- dynamic(capital_status/1).\n:- dynamic(funding_source/1).\n:- dynamic(stated_rate/1).\n:- dynamic(margin_rate/1).\n:- dynamic(breakeven_months/1).\n:- dynamic(personal_runway/1).\n:- dynamic(cash_cycle/1).\n:- dynamic(competition/1).\n:- dynamic(differentiation/1).\n:- dynamic(dependency/1).\n:- dynamic(legal_status/1).\n\n% ------------------------------------------------------------\n% SRS 4.2 - arithmetic\n% ------------------------------------------------------------\n\n% capital_requirement = startup_cost + (6 x monthly_operating_cost)\ncapital_requirement(C) :-\n    startup_cost(S),\n    monthly_cost(M),\n    C is S + 6 * M.\n\n% funded_months = max(0, capital_available - startup_cost) / monthly_cost\n% Written as a conditional rather than max/2: Tau-Prolog's evaluable\n% functor coverage is thinner than SWI's.\nfunded_months(F) :-\n    capital_available(A),\n    startup_cost(S),\n    monthly_cost(M),\n    M > 0,\n    Spare is A - S,\n    (   Spare > 0\n    ->  F is Spare / M\n    ;   F = 0\n    ).\n\n% survival_gap = funded_months - breakeven_months\nsurvival_gap(G) :-\n    funded_months(F),\n    breakeven_months(B),\n    G is F - B.\n\n% ------------------------------------------------------------\n% Margin: numeric input -> category (decision 1)\n% SRS 3.5 rule of thumb: above 30% retail, above 45% services.\n% ------------------------------------------------------------\n\nmargin_floor(retail, 30).\nmargin_floor(food, 30).\nmargin_floor(service, 45).\nmargin_floor(online, 45).\nmargin_floor(education, 45).\nmargin_floor(professional_service, 45).\nmargin_floor(owner_trade, 45).\n\nmargin_level(L) :-\n    margin_rate(R),\n    business_type(T),\n    margin_floor(T, Floor),\n    Strong is Floor + 15,\n    (   R >= Strong ->  L = strong\n    ;   R >= Floor  ->  L = adequate\n    ;                   L = low\n    ).\n\n% ------------------------------------------------------------\n% Cost of the money funding the business (needed by R11).\n% Own savings and interest-free family money cost nothing.\n% Any borrowed source uses the rate the user stated; if no rate\n% is known this simply fails, so R11 cannot fire on a guess\n% (NFR-Robustness: the system must not invent defaults).\n% ------------------------------------------------------------\n\nfree_capital(own_savings).\nfree_capital(family_interest_free).\n\neffective_funding_cost(0) :-\n    funding_source(S),\n    free_capital(S).\neffective_funding_cost(R) :-\n    funding_source(S),\n    \\+ free_capital(S),\n    stated_rate(R).\n\n% ------------------------------------------------------------\n% Critical unknowns - SRS 9.1 step 2 (decision 4)\n% Demand, price, capital and legal status are the four inputs\n% that block a positive answer when they are not known.\n% ------------------------------------------------------------\n\ncritical_unknown(demand) :-\n    demand_evidence(unknown).\ncritical_unknown(price) :-\n    price_status(P),\n    member(P, [assumed, unknown]).\ncritical_unknown(capital) :-\n    capital_status(unknown).\ncritical_unknown(legal) :-\n    legal_status(unknown).\n","boss_rules.pl":"% ============================================================\n% B0SS - boss_rules.pl\n% The 25 expert IF-THEN rules (SRS section 7).\n%\n% Representation is the one documented in SRS 7.1:\n%     rule(Id, Conclusion, CF) :- Evidence.\n%\n% Where the expert stated two outcomes for one rule (a conclusion\n% plus a validation_gap or red_flag entry) the conclusion is an\n% and/2 term. concludes/3 in boss_infer.pl unfolds it, so rule/3\n% keeps the arity and shape the SRS shows.\n%\n% CF expresses the expert's belief in the rule conclusion when its\n% evidence is present. It is NOT a probability of business success.\n% ============================================================\n\n% ---------- Market attractiveness ----------\n\n% R01 - strongest practical evidence of a repeatable market.\nrule(r01, market_attractiveness(high), 0.8) :-\n    demand_evidence(validated),\n    repeat_demand(recurring).\n\n% R02 - real evidence plus a reachable customer group.\n% Concludes 'moderate': R01 already covers the 'high' case.\nrule(r02, market_attractiveness(moderate), 0.6) :-\n    demand_evidence(D),\n    member(D, [observed, validated]),\n    target_customer(specific).\n\n% R03 - interest or encouragement is not willingness to pay.\nrule(r03, and(market_attractiveness(low), validation_gap(test_demand)), -0.8) :-\n    demand_evidence(D),\n    member(D, [none, anecdotal]).\n\n% R04 - financial conclusions are weak until the price is checked.\nrule(r04, validation_gap(validate_price), -0.4) :-\n    price_status(assumed).\n\n% ---------- Competitive position ----------\n\n% R05 - a small entrant cannot rely on an undifferentiated price fight.\nrule(r05, competitive_position(weak), -0.8) :-\n    competition(many_strong),\n    differentiation(D),\n    member(D, [none, price_only]).\n\n% R06 - a specific reason to choose the business can offset crowding.\nrule(r06, competitive_position(strong), 0.6) :-\n    competition(C),\n    member(C, [few, many_weak]),\n    differentiation(strong).\n\n% ---------- Financial readiness ----------\n\n% R07 - funded through startup and six months from a safe source.\nrule(r07, financial_readiness(ready), 0.8) :-\n    capital_available(A),\n    capital_requirement(R),\n    A >= R,\n    funding_source(S),\n    safe_funding(S).\n\n% R08 - underfunded; the plan should be reduced or delayed.\n% Concludes 'marginal': R09 already covers the severe case.\nrule(r08, financial_readiness(marginal), -0.6) :-\n    capital_available(A),\n    capital_requirement(R),\n    Half is 0.5 * R,\n    A >= Half,\n    A < R.\n\n% R09 - unlikely to stay open long enough to test the market.\nrule(r09, and(overall_risk(high), red_flag(severe_underfunding)), -0.8) :-\n    capital_available(A),\n    capital_requirement(R),\n    Half is 0.5 * R,\n    A < Half.\n\n% ---------- Absolute overrides ----------\n\n% R10 - risky funding can endanger the household.\nrule(r10, recommendation(not_recommended), -1.0) :-\n    funding_source(S),\n    dangerous_funding(S).\n\n% R11 - each sale destroys value at the financing cost.\nrule(r11, recommendation(not_recommended), -1.0) :-\n    margin_rate(M),\n    effective_funding_cost(C),\n    M < C.\n\n% ---------- Margin, cash cycle and survival ----------\n\n% R12 - healthy margin and early cash collection make mistakes survivable.\nrule(r12, financial_readiness(ready), 0.6) :-\n    margin_level(L),\n    member(L, [adequate, strong]),\n    cash_cycle(C),\n    member(C, [advance_payment, on_delivery]).\n\n% R13 - money is tied up before cash returns to the business.\nrule(r13, overall_risk(high), -0.6) :-\n    cash_cycle(C),\n    member(C, [long_credit, heavy_stock]),\n    \\+ holds_upto(1, financial_readiness(ready)).\n\n% R14 - expected to run out of funded time before break-even.\nrule(r14, and(overall_risk(high), survival_runway(insufficient)), -0.8) :-\n    breakeven_months(B),\n    funded_months(F),\n    B > F.\n\n% ---------- Owner readiness ----------\n\n% R15 - hands-on experience reduces operating and quality-control errors.\nrule(r15, owner_readiness(strong), 0.8) :-\n    owner_experience(direct).\n\n% R16 - learning is expensive when the commitment cannot be reversed.\nrule(r16, owner_readiness(weak), -0.8) :-\n    owner_experience(none),\n    reversibility(low).\n\n% R17 - low-cost reversible starts allow the owner to learn safely.\nrule(r17, owner_readiness(adequate), 0.4) :-\n    owner_experience(none),\n    reversibility(high).\n\n% ---------- Operations ----------\n\n% R18 - a walk-in business must be available during customer hours.\nrule(r18, operational_readiness(not_ready), -0.6) :-\n    owner_time(insufficient),\n    channel_type(walk_in).\n\n% R19 - one customer, supplier, person or platform is a single point of failure.\nrule(r19, and(overall_risk(high), red_flag(concentration)), -0.6) :-\n    dependency(high).\n\n% R20 - household pressure forces damaging short-term business decisions.\nrule(r20, and(overall_risk(high), red_flag(household_exposure)), -0.8) :-\n    personal_runway(P),\n    P < 3,\n    breakeven_months(B),\n    B > 6.\n\n% R21 - the business cannot legally operate in the proposed form.\nrule(r21, recommendation(not_recommended), -1.0) :-\n    legal_status(blocking).\n\n% ---------- Final recommendation rules ----------\n\n% R22 - report insufficient basis rather than guess.\n% \\+ \\+ gives exactly one solution however many unknowns exist.\nrule(r22, recommendation(further_validation_required), 0.0) :-\n    \\+ \\+ critical_unknown(_).\n\n% R23 - nothing in the screening currently argues against detailed planning.\nrule(r23, recommendation(proceed), 0.8) :-\n    \\+ absolute_override,\n    \\+ critical_unknown(_),\n    core_positive,\n    holds(financial_readiness(ready)),\n    holds(owner_readiness(O)),\n    member(O, [adequate, strong]),\n    \\+ weakness(_).\n\n% R24 - the opportunity may continue only with stated mitigations.\nrule(r24, recommendation(proceed_with_caution), 0.6) :-\n    \\+ absolute_override,\n    \\+ critical_unknown(_),\n    core_positive,\n    weakness_count(N),\n    N > 0,\n    N =< 2.\n\n% R25 - the current scale/model should change before reassessment.\nrule(r25, recommendation(not_recommended_in_this_form), -0.8) :-\n    \\+ absolute_override,\n    \\+ critical_unknown(_),\n    severe_risk_count(N),\n    N >= 2.\n","boss_infer.pl":"% ============================================================\n% B0SS - boss_infer.pl\n% Inference control: rule stratification, severity tables and the\n% SRS section 9.1 priority ladder.\n%\n% Backward chaining is the query strategy (SRS section 4). Rules\n% are grouped into levels so that a rule which asks what another\n% rule concluded can never re-enter its own body:\n%\n%   level 1  intermediate conclusions drawn straight from facts\n%   level 2  intermediate conclusions that consult level 1 (R13)\n%   level 3  recommendation rules (overrides and final verdicts)\n%\n% holds/1 exposes levels 1-2 only, so the final rules can read the\n% intermediate picture while remaining outside it.\n% ============================================================\n\nrule_level(r01, 1). rule_level(r02, 1). rule_level(r03, 1).\nrule_level(r04, 1). rule_level(r05, 1). rule_level(r06, 1).\nrule_level(r07, 1). rule_level(r08, 1). rule_level(r09, 1).\nrule_level(r12, 1). rule_level(r14, 1). rule_level(r15, 1).\nrule_level(r16, 1). rule_level(r17, 1). rule_level(r18, 1).\nrule_level(r19, 1). rule_level(r20, 1).\nrule_level(r13, 2).\nrule_level(r10, 3). rule_level(r11, 3). rule_level(r21, 3).\nrule_level(r22, 3). rule_level(r23, 3). rule_level(r24, 3).\nrule_level(r25, 3).\n\n% Unfold an and/2 conclusion into its individual conclusions.\nunfold(and(A, B), C) :- !, ( unfold(A, C) ; unfold(B, C) ).\nunfold(C, C).\n\n% A rule fires when its body succeeds. Id is always bound before\n% rule/3 is called, so only that one clause is ever executed.\nfires(Id) :-\n    rule_level(Id, _),\n    rule(Id, _, _).\n\n% What an applicable rule up to level L concludes.\nholds_upto(L, C) :-\n    rule_level(Id, RL),\n    RL =< L,\n    rule(Id, Concl, _),\n    unfold(Concl, C).\n\n% Intermediate conclusions visible to the final recommendation rules.\nholds(C) :- holds_upto(2, C).\n\n% ------------------------------------------------------------\n% Severity tables (decision 3)\n% These make the SRS's prose thresholds - \"at most two manageable\n% weaknesses\", \"two or more severe unmitigated risks\" - countable,\n% and keep them editable in one place.\n% ------------------------------------------------------------\n\nsevere_risk(no_market)           :- holds(market_attractiveness(low)).\nsevere_risk(owner_unready)       :- holds(owner_readiness(weak)).\nsevere_risk(competitive_weak)    :- holds(competitive_position(weak)).\nsevere_risk(severe_underfunding) :- holds(red_flag(severe_underfunding)).\nsevere_risk(concentration)       :- holds(red_flag(concentration)).\nsevere_risk(household_exposure)  :- holds(red_flag(household_exposure)).\nsevere_risk(survival_runway)     :- holds(survival_runway(insufficient)).\n\nweakness(W) :- severe_risk(W).\nweakness(financial_marginal)     :- holds(financial_readiness(marginal)).\nweakness(operations_not_ready)   :- holds(operational_readiness(not_ready)).\nweakness(cash_cycle_slow) :-\n    holds(overall_risk(high)),\n    cash_cycle(C),\n    member(C, [long_credit, heavy_stock]).\n\nsevere_risk_count(N) :-\n    findall(R, severe_risk(R), L0),\n    sort(L0, L),\n    length(L, N).\n\nweakness_count(N) :-\n    findall(W, weakness(W), L0),\n    sort(L0, L),\n    length(L, N).\n\n% The core case the expert checks before any softer factor.\ncore_positive :-\n    \\+ \\+ ( holds(market_attractiveness(M)), member(M, [high, moderate]) ),\n    \\+ holds(owner_readiness(weak)),\n    \\+ holds(red_flag(severe_underfunding)).\n\n% ------------------------------------------------------------\n% Absolute overrides - SRS 8.1: R10, R11 and R21 bypass all\n% positive evidence.\n% ------------------------------------------------------------\n\nabsolute_override :-\n    member(Id, [r10, r11, r21]),\n    rule(Id, _, _),\n    !.\n\noverride_rule(Id) :-\n    member(Id, [r10, r11, r21]),\n    rule(Id, _, _).\n\n% ------------------------------------------------------------\n% SRS 9.1 priority order\n% ------------------------------------------------------------\n\nrecommendation(Rec, CF) :-\n    (   absolute_override\n    ->  Rec = not_recommended,               CF = -1.0\n    ;   critical_unknown(_)\n    ->  Rec = further_validation_required,   CF = 0.0\n    ;   fires(r23)\n    ->  Rec = proceed,                       CF = 0.8\n    ;   fires(r24)\n    ->  Rec = proceed_with_caution,          CF = 0.6\n    ;   fires(r25)\n    ->  Rec = not_recommended_in_this_form,  CF = -0.8\n    ;   Rec = further_validation_required,   CF = 0.0\n    ).\n\n% ------------------------------------------------------------\n% Explanation support - SRS section 10 / FR-08 / FR-09\n% ------------------------------------------------------------\n\n% Every rule that fired, with its conclusion and CF, strongest first.\ntrace(Trace) :-\n    findall(t(Abs, Id, Concl, CF),\n            ( fires(Id), rule(Id, Concl, CF), Abs is -abs(CF) ),\n            L0),\n    sort(L0, L1),\n    findall(fired(Id, Concl, CF), member(t(_, Id, Concl, CF), L1), Trace).\n\npositives(Top) :-\n    trace(T),\n    findall(fired(Id, C, CF), ( member(fired(Id, C, CF), T), CF > 0 ), L),\n    first_n(3, L, Top).\n\nconcerns(Top) :-\n    trace(T),\n    findall(fired(Id, C, CF), ( member(fired(Id, C, CF), T), CF < 0 ), L),\n    first_n(3, L, Top).\n\nmissing(M) :-\n    findall(U, critical_unknown(U), L0),\n    sort(L0, M).\n\ngaps(G) :-\n    findall(Item, holds(validation_gap(Item)), L0),\n    sort(L0, G).\n\nred_flags(F) :-\n    findall(Flag, holds(red_flag(Flag)), L0),\n    sort(L0, F).\n\nfirst_n(0, _, []) :- !.\nfirst_n(_, [], []) :- !.\nfirst_n(N, [H|T], [H|R]) :- N1 is N - 1, first_n(N1, T, R).\n\n% ------------------------------------------------------------\n% Single entry point queried by the interface.\n% ------------------------------------------------------------\n\nassess(assessment(Rec, CF, Pos, Con, Missing, Gaps, Flags, Trace, Money)) :-\n    recommendation(Rec, CF),\n    positives(Pos),\n    concerns(Con),\n    missing(Missing),\n    gaps(Gaps),\n    red_flags(Flags),\n    trace(Trace),\n    money(Money).\n\n% Visible arithmetic for the explanation (SRS section 10).\nmoney(money(Req, Funded, Gap)) :-\n    ( capital_requirement(R) -> Req = R ; Req = unknown ),\n    ( funded_months(F)       -> Funded = F ; Funded = unknown ),\n    ( survival_gap(G)        -> Gap = G ; Gap = unknown ).\n","boss_advice.pl":"% ============================================================\n% B0SS - boss_advice.pl\n% Presentation knowledge: what each rule means in plain business\n% language, and the specific next action for every concern\n% (SRS section 10). Kept in the knowledge base rather than the\n% interface so it can be edited without touching the UI (FR-11).\n% ============================================================\n\n% ---------- Plain-language reading of each rule ----------\n\nrule_text(r01, 'Repeat customers have already paid at your intended price.').\nrule_text(r02, 'There is observed demand and you know exactly who the customer is.').\nrule_text(r03, 'Nobody has paid yet - interest and encouragement are not demand.').\nrule_text(r04, 'Your price is an assumption that has not been tested against the market.').\nrule_text(r05, 'Strong competitors and nothing specific that makes a customer choose you.').\nrule_text(r06, 'A clear reason to choose you offsets the number of competitors.').\nrule_text(r07, 'Capital covers startup plus six months of running costs, from a safe source.').\nrule_text(r08, 'You have most of the money you need, but not all of it.').\nrule_text(r09, 'You have less than half the money this plan requires.').\nrule_text(r10, 'The funding source can take the household down with the business.').\nrule_text(r11, 'Your margin is below the cost of the money funding the business.').\nrule_text(r12, 'Healthy margin and you collect cash early.').\nrule_text(r13, 'Cash goes out well before it comes back in.').\nrule_text(r14, 'You run out of funded months before you reach break-even.').\nrule_text(r15, 'You have done this work yourself, not just managed it.').\nrule_text(r16, 'No hands-on experience and no cheap way to stop.').\nrule_text(r17, 'No experience yet, but the start is small and reversible.').\nrule_text(r18, 'A walk-in business needs you there during customer hours.').\nrule_text(r19, 'One customer, supplier, person or platform can end the business.').\nrule_text(r20, 'The household runs out of money before the business can pay it.').\nrule_text(r21, 'The business cannot legally operate in this form.').\nrule_text(r22, 'Something critical is still unknown, so no positive answer is possible.').\nrule_text(r23, 'Nothing in this screening argues against detailed planning.').\nrule_text(r24, 'The core case holds, with weaknesses that need explicit mitigation.').\nrule_text(r25, 'Several serious but fixable problems exist in the current plan.').\n\n% ---------- A specific next action for every concern ----------\n\nnext_action(r03, 'Before spending anything, get one real payment or a signed commitment at your intended price.').\nnext_action(r04, 'Ask three likely customers what they pay now, and check two competitors'' actual prices.').\nnext_action(r05, 'Write down the one narrow reason a customer would leave a competitor for you. If you cannot, change the offer.').\nnext_action(r08, 'Either raise the shortfall before starting, or cut the plan until your capital covers it.').\nnext_action(r09, 'Do not start at this scale. Redesign to a version you can fund for six months.').\nnext_action(r10, 'Do not fund this with money secured on the home or borrowed at high interest. Change the funding or the scale.').\nnext_action(r11, 'Recheck your margin and your interest rate. If the margin is genuinely lower, this plan loses money on every sale.').\nnext_action(r13, 'Negotiate deposits or faster payment terms before committing to stock or credit.').\nnext_action(r14, 'Reduce monthly costs or raise capital until funded months exceed your break-even estimate.').\nnext_action(r16, 'Work in this trade for a season first, or bring in a committed partner who has.').\nnext_action(r18, 'Arrange cover for customer hours, or move to a channel that does not need you present.').\nnext_action(r19, 'Get the dependency in writing and line up a second option before you launch.').\nnext_action(r20, 'Keep at least three months of household costs outside the business, or delay the start.').\nnext_action(r21, 'Confirm the licence position with the relevant authority before going further.').\n\n% ---------- Missing information -> what to go and find out ----------\n\nunknown_label(demand,  'Whether anyone will actually pay has not been tested.').\nunknown_label(price,   'The selling price has not been validated.').\nunknown_label(capital, 'How much capital you actually have is not known.').\nunknown_label(legal,   'The licensing position is not known.').\n\nunknown_action(demand,  'Test whether anyone will pay: take one deposit, pre-order or paid trial.').\nunknown_action(price,   'Validate the selling price against real competitor prices and real customer responses.').\nunknown_action(capital, 'Work out your actual startup cost and monthly running cost before deciding anything else.').\nunknown_action(legal,   'Find out exactly which licences or approvals this business needs, and whether you can get them.').\n\ngap_action(test_demand,   'Demand has not been tested with money.').\ngap_action(validate_price,'The selling price has not been validated.').\n\n% ---------- CF labels, SRS section 8 ----------\n\ncf_label(CF, 'Definitely not')    :- CF =< -0.9.\ncf_label(CF, 'Almost certainly not') :- CF > -0.9, CF =< -0.7.\ncf_label(CF, 'Probably not')      :- CF > -0.7, CF =< -0.5.\ncf_label(CF, 'Maybe not')         :- CF > -0.5, CF =< -0.3.\ncf_label(CF, 'Unknown / insufficient basis') :- CF > -0.3, CF < 0.3.\ncf_label(CF, 'Maybe')             :- CF >= 0.3, CF < 0.5.\ncf_label(CF, 'Probably')          :- CF >= 0.5, CF < 0.7.\ncf_label(CF, 'Almost certainly')  :- CF >= 0.7, CF < 0.9.\ncf_label(CF, 'Definitely')        :- CF >= 0.9.\n\n% ---------- Verdict headline text ----------\n\nverdict_text(proceed, 'PROCEED').\nverdict_text(proceed_with_caution, 'PROCEED WITH CAUTION').\nverdict_text(further_validation_required, 'FURTHER VALIDATION REQUIRED').\nverdict_text(not_recommended, 'NOT RECOMMENDED').\nverdict_text(not_recommended_in_this_form, 'NOT RECOMMENDED IN THIS FORM').\n\nverdict_blurb(proceed, 'Continue to detailed planning. This does not mean the business will succeed.').\nverdict_blurb(proceed_with_caution, 'The core case is positive, but fix the concerns below before or during launch.').\nverdict_blurb(further_validation_required, 'Something critical is unknown. Find it out before deciding; the list below is what to check.').\nverdict_blurb(not_recommended, 'A blocking condition makes this unacceptable in its current form, whatever else is strong.').\nverdict_blurb(not_recommended_in_this_form, 'Change the scale, model, dependency or timing, then assess again.').\n"};
